// @name Checkers
// @background #efe6d4
// @refresh 3600
// Checkers (English draughts) on a touch screen, against the computer or a
// second player. Tap one of your pieces to see where it can go, then tap the
// square to move there; a jump goes as far as it can by itself. Men move
// forward, kings both ways, a man reaching the far row is crowned. Jumps are
// compulsory unless the settings say otherwise. The game in progress is kept
// in the scene's state, so it outlasts a restart.
import { DRAW, chooseMove, count, legalMoves, newGame, play, readGame, remember, undo } from './logic'

// High contrast where the panel shows no color (black and white, greys), or
// when the scene's Contrast setting asks for it.
const highContrast = (app) => {
  const mode = app.state.contrast || 'auto'
  return mode === 'high' || (mode === 'auto' && app.frame.color === false)
}

const THEMES = {
  color: {
    page: 'bg-[#efe6d4] text-[#2f2a24]',
    muted: 'text-[#7c705f]',
    title: 'text-[#2f4a3a]',
    status: 'bg-[#2f4a3a] text-white',
    button: 'bg-[#e0d4bd] text-[#2f2a24] active:bg-[#d2c4a8]',
    buttonOff: 'bg-[#e8e0d0] text-[#b2a690]',
    primary: 'bg-[#a8432f] text-white active:bg-[#8a3424]',
    card: 'bg-[#fbf7ef] border-4 border-[#2f4a3a] text-[#2f2a24]',
    // The board's own colors (SVG fills).
    light: '#ebdfc4',
    dark: '#5b7f62',
    frame: '#3b4a3c',
    pieces: {
      1: { fill: '#b03a2a', rim: '#6e2016', ring: '#d8705e', crown: '#f1cf63' },
      [-1]: { fill: '#2a2e33', rim: '#0f1113', ring: '#5c636b', crown: '#f1cf63' },
    },
    pick: '#f2c94c',
    lastMove: '#f2c94c',
    names: { 1: 'Red', [-1]: 'Black' },
  },
  high: {
    page: 'bg-white text-black',
    muted: 'text-black',
    title: 'text-black',
    status: 'bg-black text-white',
    button: 'bg-white text-black border-2 border-black',
    buttonOff: 'bg-white text-black',
    primary: 'bg-black text-white',
    card: 'bg-white border-4 border-black text-black',
    light: '#ffffff',
    dark: '#000000',
    frame: '#000000',
    pick: '#ffffff',
    lastMove: '#ffffff',
    names: { 1: 'White', [-1]: 'Black' },
  },
}

const settings = (app) => ({
  versus: app.state.mode !== 'two',
  level: ['easy', 'medium', 'hard', 'expert'].indexOf(app.state.difficulty) >= 0 ? app.state.difficulty : 'medium',
  mandatory: app.state.forcedJumps !== false && app.state.forcedJumps !== 'false',
  hints: app.state.hints !== false && app.state.hints !== 'false',
  first: app.state.first === 'top' ? -1 : 1,
})

// Against the computer you are the bottom side and it plays the top.
const COMPUTER = -1

const save = (game) => frameos.setState('game', game)

/** The computer's reply, when it is its turn. */
const computerMoves = (game, s) => {
  if (!s.versus || game.winner || game.turn !== COMPUTER) return false
  const started = Date.now()
  const found = chooseMove(game.board, game.turn, s.mandatory, s.level, game)
  const reply = found.move
  if (!reply) return false
  frameos.log(`checkers: computer (${s.level}) replied in ${Date.now() - started} ms, ${found.nodes} positions, depth ${found.depth}`)
  play(game, reply, s.mandatory)
  return true
}

const loadGame = (app, s) => {
  const kept = readGame(app.state.game)
  if (kept) {
    // It is the computer's turn: a new game it starts, or the mode just changed.
    if (computerMoves(kept, s)) save(kept)
    return kept
  }
  const game = newGame(s.first, Date.now() % 2147483647)
  computerMoves(game, s)
  save(game)
  return game
}

const copyOf = (game) => readGame(JSON.parse(JSON.stringify(game)))

const startOver = (app, game) => {
  const s = settings(app)
  frameos.remember('confirm', false)
  frameos.remember('sel', -1)
  const fresh = newGame(s.first, (Date.now() ^ (game.seed * 7919)) % 2147483647)
  computerMoves(fresh, s)
  save(fresh)
}

const askNewGame = (app, game) => {
  if (game.plies === 0 || game.winner) startOver(app, game)
  else frameos.remember('confirm', true)
}

const takeBack = (app, game) => {
  const g = copyOf(game)
  if (!undo(g)) return
  // Against the computer, go back to a position where it is your move.
  if (settings(app).versus && g.turn === COMPUTER && g.history.length) undo(g)
  frameos.remember('sel', -1)
  save(g)
}

/** A tap on square `sq`: pick a piece of yours, or move the picked one there. */
const tapSquare = (app, game, sq) => {
  const s = settings(app)
  if (game.winner || frameos.recall('confirm')) return
  if (s.versus && game.turn === COMPUTER) return
  const moves = legalMoves(game.board, game.turn, s.mandatory)
  const sel = frameos.recall('sel') ?? -1
  frameos.remember('note', '')
  if (game.board[sq] * game.turn > 0) {
    const movable = moves.some((m) => m.from === sq)
    if (!movable) {
      frameos.remember('sel', -1)
      const mustJump = s.mandatory && moves.length > 0 && moves[0].caps.length > 0
      frameos.remember('note', mustJump ? 'You must jump: pick a ringed piece' : 'That piece cannot move')
      return
    }
    frameos.remember('sel', sel === sq ? -1 : sq)
    return
  }
  // Of the moves of the picked piece ending here, the one that takes the most.
  let chosen = null
  for (const m of moves) if (m.from === sel && m.to === sq && (!chosen || m.caps.length > chosen.caps.length)) chosen = m
  if (!chosen) {
    frameos.remember('sel', -1)
    return
  }
  const g = copyOf(game)
  remember(g)
  play(g, chosen, s.mandatory)
  computerMoves(g, s)
  frameos.remember('sel', -1)
  save(g)
}

// What each square shows, one signal a square, and the status line, the
// tallies and the Undo button: a tap runs only what reads them, not get().
// The game itself stays in the scene's `game` field.
const looks = Array.from({ length: 64 }, () => signal(''))
const status = signal('')
const pieces = { 1: signal(0), [-1]: signal(0) }
const kings = { 1: signal(0), [-1]: signal(0) }
const canUndo = signal(false)

// Every signal from the kept game and the selection, and what get() needs of
// the same reading.
const show = (app, game) => {
  const s = settings(app)
  const t = highContrast(app) ? THEMES.high : THEMES.color
  const confirm = !!frameos.recall('confirm')
  const sel = frameos.recall('sel') ?? -1
  const cursor = frameos.recall('keys') ? frameos.recall('cursor') ?? 46 : -1

  const yourTurn = !game.winner && !(s.versus && game.turn === COMPUTER)
  const moves = yourTurn ? legalMoves(game.board, game.turn, s.mandatory) : []
  const mustJump = s.mandatory && moves.length > 0 && moves[0].caps.length > 0
  // A square's look: its piece, then how many last-move outlines, a ring for
  // a piece that must jump, the picked ring, the stops of a jump on its way
  // and the move hints it holds (drawn as often as the moves name it), and
  // the keyboard's cursor.
  const marks = new Array(64).fill(0)
  const stops = new Array(64).fill(0)
  const targets = new Array(64).fill(0)
  const jumpers = new Array(64).fill(0)
  for (const m of game.last) for (const sq of [m.from, m.to]) marks[sq]++
  if (s.hints && sel >= 0) {
    for (const mv of moves) {
      if (mv.from !== sel) continue
      targets[mv.to]++
      // Where a jump of the picked piece lands on its way.
      for (const sq of mv.path.slice(0, -1)) stops[sq]++
    }
  }
  if (s.hints && mustJump && sel < 0) for (const m of moves) jumpers[m.from] = 1
  for (let sq = 0; sq < 64; sq++) {
    looks[sq].value = [game.board[sq], marks[sq], jumpers[sq], sel === sq ? 1 : 0, stops[sq], targets[sq], cursor === sq ? 1 : 0].join(',')
  }

  let line
  let detail = `${Math.ceil(game.plies / 2)} moves played.`
  if (game.winner === DRAW) {
    line = 'Draw'
    detail = '40 moves each without a jump or a man moving.'
  } else if (game.winner) line = s.versus ? (game.winner === 1 ? 'You win!' : 'The computer wins') : `${t.names[game.winner]} wins!`
  else if (s.versus) line = mustJump ? 'Your move: you must jump' : 'Your move'
  else line = `${t.names[game.turn]} to move${mustJump ? ': must jump' : ''}`
  const note = !game.winner ? frameos.recall('note') || '' : ''
  if (note) line = note
  status.value = line

  for (const side of [1, -1]) {
    const n = count(game.board, side)
    pieces[side].value = n.men + n.kings
    kings[side].value = n.kings
  }
  canUndo.value = game.history.length > 0 && !confirm
  return { s, t, confirm, status: line, detail }
}

// A tap: the game as kept now (never one a handler of an earlier render
// held), changed by `act`. A card over the board (New game?, the result)
// comes or goes only with a whole get(): a tap that shows or hides one sets
// no signal.
const tap = (app, act) => {
  const covered = (game) => !!frameos.recall('confirm') || !!game.winner
  const before = covered(loadGame(app, settings(app)))
  act(loadGame(app, settings(app)))
  const game = loadGame(app, settings(app))
  if (!before && !covered(game)) show(app, game)
}

// A keyboard on a Pi: arrows move a cursor, Enter or space taps it.
export function onEvent(app, context) {
  const s = settings(app)
  const game = loadGame(app, s)
  const p = context.payload || {}
  if (context.event === 'back') {
    takeBack(app, game)
    return true
  }
  if (context.event !== 'keyDown' || p.ctrl || p.alt || p.meta) return false
  const key = String(p.key || '')
  if (frameos.recall('confirm')) {
    if (key === 'Enter' || key === 'y') startOver(app, game)
    else if (key === 'Escape' || key === 'n') frameos.remember('confirm', false)
    else return false
    return true
  }
  const cursor = frameos.recall('cursor') ?? 46
  const moves = { ArrowUp: -8, ArrowDown: 8, ArrowLeft: -1, ArrowRight: 1 }
  if (key in moves) {
    const next = cursor + moves[key]
    const ok = next >= 0 && next < 64 && !(key === 'ArrowLeft' && (cursor & 7) === 0) && !(key === 'ArrowRight' && (cursor & 7) === 7)
    frameos.remember('cursor', ok ? next : cursor)
    frameos.remember('keys', true)
    return true
  }
  if (key === 'Enter' || key === ' ') {
    frameos.remember('keys', true)
    tapSquare(app, game, cursor)
    return true
  }
  if (key === 'u' || key === 'Backspace') {
    takeBack(app, game)
    return true
  }
  if (key === 'n') {
    askNewGame(app, game)
    return true
  }
  return false
}

// A crown (Material Design Icons' "crown"), in a 24 box.
const CROWN = 'M5 16 3 5l5.5 5L12 4l3.5 6L21 5l-2 11H5m14 3c0 .6-.4 1-1 1H6c-.6 0-1-.4-1-1v-1h14v1z'

/** One piece on the board, centred on (cx, cy). */
const Piece = ({ value, cx, cy, s, hc, t }) => {
  const side = value > 0 ? 1 : -1
  const king = value === 2 || value === -2
  const r = s * 0.4
  const crownScale = (s * 0.5) / 24
  const crown = (color) =>
    king ? (
      <g transform={`translate(${cx - s * 0.25} ${cy - s * 0.26}) scale(${crownScale})`}>
        <path d={CROWN} fill={color} />
      </g>
    ) : null
  if (hc) {
    // On black squares: white pieces solid white, black pieces black with a
    // thin white rim, so the two never look alike.
    if (side === 1) {
      return (
        <g>
          <circle cx={cx} cy={cy} r={r} fill="#ffffff" />
          {crown('#000000')}
        </g>
      )
    }
    return (
      <g>
        <circle cx={cx} cy={cy} r={r} fill="#ffffff" />
        <circle cx={cx} cy={cy} r={r - s * 0.04} fill="#000000" />
        {crown('#ffffff')}
      </g>
    )
  }
  const c = t.pieces[side]
  return (
    <g>
      <circle cx={cx} cy={cy + s * 0.03} r={r} fill={c.rim} />
      <circle cx={cx} cy={cy} r={r} fill={c.fill} stroke={c.rim} strokeWidth={s * 0.03} />
      <circle cx={cx} cy={cy} r={r * 0.68} fill="none" stroke={c.ring} strokeWidth={s * 0.035} />
      {crown(c.crown)}
    </g>
  )
}

const repeat = (n, draw) => Array.from({ length: n }, draw)

// One square, from its look, in the order the board paints: the dark square,
// the last moves' outlines, the rings, the piece, the stops, the hints and
// the cursor. Nothing drawn on a square reaches past it.
const Square = memo(({ sq, s, hc, t }) => {
  const [piece, marks, jumper, picked, stops, targets, cursor] = looks[sq].value.split(',').map(Number)
  const x = (sq & 7) * s
  const y = (sq >> 3) * s
  const ring = (width) => (
    <rect x={x + width / 2} y={y + width / 2} width={s - width} height={s - width} fill="none" stroke={t.pick} strokeWidth={width} />
  )
  return (
    <g>
      {((sq >> 3) + (sq & 7)) % 2 === 1 ? <rect x={x} y={y} width={s} height={s} fill={t.dark} /> : null}
      {repeat(marks, () => (
        <rect x={x + s * 0.06} y={y + s * 0.06} width={s * 0.88} height={s * 0.88}
          fill="none" stroke={t.lastMove} strokeWidth={s * 0.035} strokeDasharray={`${s * 0.12} ${s * 0.08}`} />
      ))}
      {jumper ? ring(s * 0.05) : null}
      {picked ? ring(s * 0.09) : null}
      {piece ? <Piece value={piece} cx={x + s / 2} cy={y + s / 2} s={s} hc={hc} t={t} /> : null}
      {repeat(stops, () => (
        <circle cx={x + s / 2} cy={y + s / 2} r={s * 0.1} fill="none" stroke={t.pick} strokeWidth={s * 0.04} />
      ))}
      {repeat(targets, () => (
        <circle cx={x + s / 2} cy={y + s / 2} r={s * 0.17} fill={hc ? '#000000' : t.pick} stroke={hc ? '#ffffff' : '#3b3a2a'} strokeWidth={s * 0.05} />
      ))}
      {cursor ? (
        <rect x={x + s * 0.02} y={y + s * 0.02} width={s * 0.96} height={s * 0.96} fill="none"
          stroke={hc ? '#ffffff' : '#1d4ed8'} strokeWidth={s * 0.04} strokeDasharray={`${s * 0.06} ${s * 0.06}`} />
      ) : null}
    </g>
  )
})

const Board = ({ px, hc, t }) => {
  const s = px / 8
  const squares = []
  for (let sq = 0; sq < 64; sq++) squares.push(<Square sq={sq} s={s} hc={hc} t={t} />)
  return (
    <svg viewBox={`0 0 ${px} ${px}`} width={px} height={px}>
      <rect width={px} height={px} fill={t.light} />
      {squares}
    </svg>
  )
}

// A side's pieces: a disc, how many, and (with room) whose and their kings.
const Tally = memo(({ side, compact, font, hc, t, name }) => {
  const n = pieces[side].value
  const k = kings[side].value
  return (
    <div className="flex items-center gap-2">
      <svg viewBox="0 0 24 24" className={`w-[${font * 1.3}px] h-[${font * 1.3}px]`}>
        {hc ? (
          side === 1 ? (
            <circle cx={12} cy={12} r={10} fill="#ffffff" stroke="#000000" strokeWidth={2} />
          ) : (
            <circle cx={12} cy={12} r={10} fill="#000000" />
          )
        ) : (
          <circle cx={12} cy={12} r={10} fill={t.pieces[side].fill} stroke={t.pieces[side].rim} strokeWidth={2} />
        )}
      </svg>
      <span className={`text-[${font}px] font-bold`}>{n}</span>
      {compact ? null : <span className={`text-[${Math.round(font * 0.75)}px] ${t.muted}`}>{name}</span>}
      {k && !compact ? <span className={`text-[${Math.round(font * 0.75)}px] ${t.muted}`}>{`${k} ${k === 1 ? 'king' : 'kings'}`}</span> : null}
    </div>
  )
})

const WideStatus = memo(({ font, t }) => (
  <div className={`rounded-xl px-4 py-3 text-[${font}px] font-bold leading-tight ${t.status}`}>{status.value}</div>
))
const NarrowStatus = memo(({ font, t }) => (
  <div className={`flex-1 min-w-0 rounded-xl px-3 h-full flex items-center text-[${font}px] font-bold truncate ${t.status}`}>{status.value}</div>
))
const UndoButton = memo(({ app, buttonH, font, t }) => (
  <div className={`flex-1 h-[${buttonH}px] rounded-xl flex items-center justify-center text-[${font}px] font-bold ${canUndo.value ? t.button : t.buttonOff}`}
    onClick={() => tap(app, (game) => takeBack(app, game))}>
    Undo
  </div>
))

export function get(app, context) {
  const W = context.imageWidth ?? app.frame.width
  const H = context.imageHeight ?? app.frame.height
  const hc = highContrast(app)
  const game = loadGame(app, settings(app))
  const { s, t, confirm, status, detail } = show(app, game)

  const name = (side) => (s.versus ? (side === 1 ? 'You' : 'Computer') : t.names[side])

  const m = Math.round(Math.min(W, H) * 0.04)
  const wide = W >= H * 1.2
  // A tall screen has room for the name over the status.
  const titled = !wide && H >= W * 1.4
  const headerH = wide ? 0 : Math.round(Math.max(48, H * 0.09))
  const titleH = titled ? Math.round(H * 0.08) : 0
  const footH = wide ? 0 : Math.round(Math.max(52, Math.min(H * 0.1, 88)))
  const board = Math.floor((wide ? Math.min(H - 2 * m, (W - 3 * m) * 0.64) : Math.min(W - 2 * m, H - headerH - titleH - footH - (titled ? 5 : 4) * m)) / 8) * 8
  const panelW = wide ? W - board - 3 * m : W - 2 * m
  const font = Math.round(Math.max(16, Math.min(wide ? panelW * 0.075 : W * 0.045, 40)))
  const buttonH = Math.round(Math.max(48, Math.min(font * 2.4, 96)))

  const tally = (side, compact) => <Tally side={side} compact={compact} font={font} hc={hc} t={t} name={name(side)} />

  const card = (title, line, buttons) => (
    <div className={`absolute left-[${Math.round(board * 0.1)}px] right-[${Math.round(board * 0.1)}px] top-[${Math.round(board * 0.28)}px] rounded-2xl p-[${Math.round(board * 0.05)}px] flex flex-col items-center gap-3 ${t.card}`}>
      <span className={`text-[${Math.round(board * 0.08)}px] font-bold text-center`}>{title}</span>
      {line ? <span className={`text-[${Math.round(Math.max(16, board * 0.042))}px] text-center`}>{line}</span> : null}
      <div className="flex gap-3">{buttons}</div>
    </div>
  )
  const cardButton = (label, cls, onClick) => (
    <div className={`h-[${buttonH}px] px-5 rounded-xl flex items-center text-[${font}px] font-bold ${cls}`} onClick={onClick}>
      {label}
    </div>
  )
  let overlay = null
  if (confirm) {
    overlay = card('New game?', 'The game in progress will be lost.', [
      cardButton('Cancel', t.button, () => frameos.remember('confirm', false)),
      cardButton('New game', t.primary, () => tap(app, (game) => startOver(app, game))),
    ])
  } else if (game.winner) {
    overlay = card(status, detail, [
      game.history.length ? cardButton('Undo', t.button, () => tap(app, (game) => takeBack(app, game))) : null,
      cardButton('New game', t.primary, () => tap(app, (game) => startOver(app, game))),
    ])
  }

  const boardBox = (
    <div className={`relative w-[${board + 2 * Math.round(m / 2)}px] h-[${board + 2 * Math.round(m / 2)}px] shrink-0 p-[${Math.round(m / 2)}px] rounded-xl bg-[${t.frame}]`}>
      <div className={`w-[${board}px] h-[${board}px]`}
        onClick={(e) => tap(app, (game) => tapSquare(app, game, Math.min(7, Math.floor((e.localY / e.height) * 8)) * 8 + Math.min(7, Math.floor((e.localX / e.width) * 8))))}>
        <Board px={board} hc={hc} t={t} />
      </div>
      {overlay}
    </div>
  )

  const undoButton = <UndoButton app={app} buttonH={buttonH} font={font} t={t} />
  const newButton = (
    <div className={`flex-1 h-[${buttonH}px] rounded-xl flex items-center justify-center text-[${font}px] font-bold ${t.primary}`}
      onClick={() => tap(app, (game) => askNewGame(app, game))}>
      New game
    </div>
  )
  const subtitle = s.versus ? `Against the computer, ${s.level}` : 'Two players'

  if (wide) {
    return (
      <div className={`flex w-full h-full p-[${m}px] gap-[${m}px] items-center ${t.page}`}>
        {boardBox}
        <div className="flex-1 h-full flex flex-col justify-between gap-3">
          <div className="flex flex-col">
            <span className={`text-[${Math.round(font * 2)}px] font-black leading-none ${t.title}`}>Checkers</span>
            <span className={`text-[${Math.round(font * 0.75)}px] ${t.muted}`}>{subtitle}</span>
          </div>
          <WideStatus font={font} t={t} />
          <div className="flex flex-col gap-2">
            {tally(COMPUTER, false)}
            {tally(1, false)}
          </div>
          <div className="flex gap-3">
            {undoButton}
            {newButton}
          </div>
        </div>
      </div>
    )
  }
  return (
    <div className={`flex flex-col w-full h-full p-[${m}px] gap-[${m}px] items-center justify-between ${t.page}`}>
      {titled ? (
        <div className={`flex w-full h-[${titleH}px] items-end justify-between`}>
          <span className={`text-[${Math.round(titleH * 0.8)}px] font-black leading-none ${t.title}`}>Checkers</span>
          <span className={`flex-1 min-w-0 ml-4 text-right truncate text-[${Math.round(font * 0.75)}px] ${t.muted}`}>{s.versus ? s.level : 'Two players'}</span>
        </div>
      ) : null}
      <div className={`flex w-full h-[${headerH}px] items-center gap-3`}>
        <NarrowStatus font={font} t={t} />
        {tally(COMPUTER, true)}
        {tally(1, true)}
      </div>
      {boardBox}
      <div className={`flex w-full h-[${footH}px] gap-3`}>
        {undoButton}
        {newButton}
      </div>
    </div>
  )
}

