// The rules of checkers (English draughts) and a small computer player, with
// no drawing. The board is 64 numbers, row by row from the top: 0 empty,
// 1 a man of the bottom side, 2 its king, -1 a man of the top side, -2 its
// king. Only the dark squares ((row + col) odd) are ever used. The bottom side
// moves up, the top side down. Plain values only, so a game fits in the
// scene's state as JSON.

/** One move: where it starts and ends, the squares it lands on and the pieces it takes. */
export type Move = { from: number; to: number; path: number[]; caps: number[] }

// The four diagonals as steps: up-left, up-right, down-left, down-right.
// NEXT[sq * 4 + k] is the square one step from sq along diagonal k, or -1
// off the board; worked out once, so the computer's search does no
// arithmetic on rows and columns.
const NEXT: number[] = []
for (let sq = 0; sq < 64; sq++) {
  const r = sq >> 3
  const c = sq & 7
  for (const [dr, dc] of [[-1, -1], [-1, 1], [1, -1], [1, 1]]) {
    const rr = r + dr
    const cc = c + dc
    NEXT.push(rr < 0 || rr > 7 || cc < 0 || cc > 7 ? -1 : rr * 8 + cc)
  }
}

/** A new board: twelve men each on the three rows nearest their side. */
export function startBoard(): number[] {
  const board = new Array(64).fill(0)
  for (let sq = 0; sq < 64; sq++) {
    const r = sq >> 3
    const c = sq & 7
    if ((r + c) % 2 === 0) continue
    if (r < 3) board[sq] = -1
    else if (r > 4) board[sq] = 1
  }
  return board
}

// The diagonals a piece may take: men only forward, kings any way.
function firstDir(piece: number): number {
  return piece === -1 ? 2 : 0
}
function lastDir(piece: number): number {
  return piece === 1 ? 1 : 3
}

function promotes(piece: number, sq: number): boolean {
  return (piece === 1 && sq < 8) || (piece === -1 && sq >= 56)
}

/** Whether the piece on `from` can jump at all: the cheap test before the full search. */
function canJump(board: number[], from: number, piece: number): boolean {
  for (let k = firstDir(piece); k <= lastDir(piece); k++) {
    const mid = NEXT[from * 4 + k]
    if (mid < 0 || board[mid] * piece >= 0) continue
    const land = NEXT[mid * 4 + k]
    if (land >= 0 && board[land] === 0) return true
  }
  return false
}

/**
 * Every jump sequence of `piece` (which started on `from`) from `sq` on,
 * taken as far as it goes: a man that reaches the far row is crowned and
 * stops there. `path` and `caps` are the sequence so far.
 */
function jumpsOn(board: number[], from: number, piece: number, sq: number, path: number[], caps: number[], out: Move[]) {
  let further = false
  for (let k = firstDir(piece); k <= lastDir(piece); k++) {
    const mid = NEXT[sq * 4 + k]
    if (mid < 0 || board[mid] * piece >= 0 || caps.indexOf(mid) >= 0) continue
    const land = NEXT[mid * 4 + k]
    if (land < 0 || (board[land] !== 0 && land !== from)) continue
    further = true
    path.push(land)
    caps.push(mid)
    if (promotes(piece, land)) out.push({ from, to: land, path: path.slice(), caps: caps.slice() })
    else jumpsOn(board, from, piece, land, path, caps, out)
    path.pop()
    caps.pop()
  }
  if (!further && caps.length) out.push({ from, to: sq, path: path.slice(), caps: caps.slice() })
}

/** Every jump for `side`. */
export function captures(board: number[], side: number, into?: any[]): Move[] {
  const out: any[] = into || []
  for (let sq = 0; sq < 64; sq++) {
    const piece = board[sq]
    if (piece * side > 0 && canJump(board, sq, piece)) jumpsOn(board, sq, piece, sq, [], [], out)
  }
  return out
}

/**
 * Every legal move for `side`. With `mandatory`, a side that can jump must;
 * without, jumps and plain moves are offered together (a jump once begun is
 * still taken as far as it goes).
 */
export function legalMoves(board: number[], side: number, mandatory: boolean): Move[] {
  const jumps = captures(board, side)
  if (jumps.length && mandatory) return jumps
  const out = jumps
  for (let sq = 0; sq < 64; sq++) {
    const piece = board[sq]
    if (piece * side <= 0) continue
    for (let k = firstDir(piece); k <= lastDir(piece); k++) {
      const to = NEXT[sq * 4 + k]
      if (to >= 0 && board[to] === 0) out.push({ from: sq, to, path: [to], caps: [] })
    }
  }
  return out
}

/** Plays a move on the board in place; returns what it needs to be taken back. */
export function apply(board: number[], move: Move): { piece: number; taken: number[] } {
  const piece = board[move.from]
  const taken: number[] = []
  for (const sq of move.caps) {
    taken.push(board[sq])
    board[sq] = 0
  }
  board[move.from] = 0
  board[move.to] = promotes(piece, move.to) ? piece * 2 : piece
  return { piece, taken }
}

function takeBack(board: number[], move: Move, undo: { piece: number; taken: number[] }) {
  board[move.to] = 0
  board[move.from] = undo.piece
  for (let i = 0; i < move.caps.length; i++) board[move.caps[i]] = undo.taken[i]
}

export function count(board: number[], side: number): { men: number; kings: number } {
  let men = 0
  let kings = 0
  for (const v of board) {
    if (v * side <= 0) continue
    if (v === 1 || v === -1) men++
    else kings++
  }
  return { men, kings }
}

// --- the computer player ---------------------------------------------------

// Small bonuses on top of the material: the centre, the home row (which keeps
// the other side from crowning), and men that have come forward. Worked out
// once per kind of piece: WORTH[(piece + 2) * 64 + sq] is what that piece on
// that square is worth to its own side.
const WORTH: number[] = new Array(5 * 64).fill(0)
for (let sq = 0; sq < 64; sq++) {
  const r = sq >> 3
  const c = sq & 7
  const centre = r >= 2 && r <= 5 && c >= 2 && c <= 5 ? 4 : 0
  for (const piece of [-2, -1, 1, 2]) {
    let worth
    if (piece === 2 || piece === -2) worth = 170 + centre
    else {
      const advanced = piece === 1 ? 7 - r : r
      worth = 100 + advanced * 3 + (advanced === 0 ? 6 : 0) + centre
    }
    WORTH[(piece + 2) * 64 + sq] = worth
  }
}

/** The position's worth for `side`, in hundredths of a man. */
export function evaluate(board: number[], side: number): number {
  let score = 0
  let pieces = 0
  for (let sq = 0; sq < 64; sq++) {
    const v = board[sq]
    if (!v) continue
    pieces++
    const worth = WORTH[(v + 2) * 64 + sq]
    score += v * side > 0 ? worth : -worth
  }
  // When ahead, trade down: the same lead counts for more with fewer pieces.
  if (score > 50) score += (24 - pieces) * 2
  else if (score < -50) score -= (24 - pieces) * 2
  return score
}

/** mulberry32 with its state in an object, so a game's seed lives in its JSON. */
export function random(holder: { seed: number }): number {
  let t = (holder.seed = (holder.seed + 0x6d2b79f5) | 0)
  t = Math.imul(t ^ (t >>> 15), t | 1)
  t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296
}

// What each level may spend: how deep it looks, how many positions and how
// many milliseconds at most (whichever runs out first), and how far below the
// best a move may be and still be picked at random.
export const LEVELS = {
  easy: { depth: 2, nodes: 300, ms: 100, margin: 70 },
  medium: { depth: 4, nodes: 1500, ms: 150, margin: 12 },
  hard: { depth: 6, nodes: 5000, ms: 220, margin: 0 },
  expert: { depth: 12, nodes: 15000, ms: 260, margin: 0 },
}

const WIN = 10000

/**
 * The moves the search looks at: jumps as Move objects, plain moves packed
 * into one number (from + to * 64), which costs no allocation. Past the
 * horizon (`jumpsOnly`) only jumps.
 */
function searchMoves(board: number[], side: number, mandatory: boolean, jumpsOnly: boolean, out: any[]): any[] {
  out.length = 0
  captures(board, side, out)
  if (jumpsOnly || (mandatory && out.length)) return out
  for (let sq = 0; sq < 64; sq++) {
    const piece = board[sq]
    if (piece * side <= 0) continue
    for (let k = firstDir(piece); k <= lastDir(piece); k++) {
      const to = NEXT[sq * 4 + k]
      if (to >= 0 && board[to] === 0) out.push(sq + to * 64)
    }
  }
  return out
}

/**
 * The computer's move for `side`: iterative deepening negamax with
 * alpha-beta, jumps searched first, and a cap on the positions looked at and
 * the time taken, so it answers quickly on any frame. A jump at the horizon
 * is played out (jumps are forced, so stopping in the middle of an exchange
 * misjudges it). Lower levels pick at random among the moves within `margin`
 * of the best.
 */
export function chooseMove(
  board: number[],
  side: number,
  mandatory: boolean,
  level: string,
  holder: { seed: number },
): { move: Move | null; nodes: number; depth: number } {
  const cfg = LEVELS[level] || LEVELS.medium
  const rootMoves = legalMoves(board, side, mandatory)
  if (rootMoves.length <= 1) return { move: rootMoves[0] || null, nodes: 0, depth: 0 }
  const work = board.slice()
  const deadline = Date.now() + cfg.ms
  let nodes = 0
  let aborted = false
  // One list of moves per ply, used again at every node of that ply: fewer
  // allocations, and fewer garbage collections in the middle of a search.
  const lists: any[][] = []

  const search = (toMove: number, depth: number, alpha: number, beta: number, ply: number): number => {
    nodes++
    if (nodes > cfg.nodes || ((nodes & 63) === 0 && Date.now() > deadline)) {
      aborted = true
      return 0
    }
    const quiet = depth <= 0
    const moves = searchMoves(work, toMove, mandatory, quiet, lists[ply] || (lists[ply] = []))
    if (!moves.length) return quiet ? evaluate(work, toMove) : -WIN + ply
    if (quiet && ply > cfg.depth + 6) return evaluate(work, toMove)
    let best = -Infinity
    for (const move of moves) {
      let score
      if (typeof move === 'number') {
        const from = move & 63
        const to = move >> 6
        const piece = work[from]
        work[from] = 0
        work[to] = promotes(piece, to) ? piece * 2 : piece
        score = -search(-toMove, depth - 1, -beta, -alpha, ply + 1)
        work[to] = 0
        work[from] = piece
      } else {
        const undo = apply(work, move)
        score = -search(-toMove, depth - 1, -beta, -alpha, ply + 1)
        takeBack(work, move, undo)
      }
      if (aborted) return 0
      if (score > best) best = score
      if (score > alpha) alpha = score
      if (alpha >= beta) break
    }
    return best
  }

  // Jumps first, then the rest; each finished depth puts its best first.
  let order = rootMoves.slice().sort((a, b) => b.caps.length - a.caps.length)
  let scored: { move: Move; score: number }[] = []
  let depthDone = 0
  for (let depth = 1; depth <= cfg.depth; depth++) {
    const results: { move: Move; score: number }[] = []
    let alpha = -Infinity
    for (const move of order) {
      const undo = apply(work, move)
      // Search each move just below the best so far less the margin: a move
      // that fails low then scores below every move worth choosing (a bound
      // equal to the best would be taken for an equal move).
      const floor = alpha - cfg.margin - 1
      const score = -search(-side, depth - 1, -Infinity, -floor, 1)
      takeBack(work, move, undo)
      if (aborted) break
      results.push({ move, score })
      if (score > alpha) alpha = score
    }
    if (aborted) {
      // A depth cut short still counts when a move searched to it beat the
      // best of the depth before (searched first, so it is in the results).
      if (!cfg.margin && results.length > 1) {
        let better = results[1]
        for (const r of results) if (r.score > better.score) better = r
        if (better !== results[0] && better.score > results[0].score) scored = [better].concat(scored.filter((r) => r.move !== better.move))
      }
      break
    }
    scored = results.sort((a, b) => b.score - a.score)
    order = scored.map((s) => s.move)
    depthDone = depth
    if (scored[0].score >= WIN - 100) break
  }
  if (!scored.length) return { move: order[0], nodes, depth: 0 }
  const top = scored[0].score
  const near = scored.filter((s) => s.score >= top - cfg.margin)
  const pick = near[Math.floor(random(holder) * near.length)] || scored[0]
  return { move: pick.move, nodes, depth: depthDone }
}

// --- a game ------------------------------------------------------------------

/** Plies in a row with no jump and no man moving: 40 moves each is a draw. */
export const DRAW_PLIES = 80
export const DRAW = 3

export type Game = {
  board: number[]
  turn: number // 1 the bottom side, -1 the top side
  quiet: number // plies since the last jump or man move
  last: Move[] // the last moves, newest last (both the person's and the reply)
  winner: number // 0 playing, 1 or -1 a side won, DRAW
  history: { board: number[]; turn: number; quiet: number; last: Move[]; plies: number }[]
  seed: number
  plies: number
}

export function newGame(firstSide: number, seed: number): Game {
  return { board: startBoard(), turn: firstSide, quiet: 0, last: [], winner: 0, history: [], seed: seed | 0, plies: 0 }
}

/** Keeps the position before a move, so undo can go back to it (the last 12). */
export function remember(game: Game) {
  game.history.push({ board: game.board.slice(), turn: game.turn, quiet: game.quiet, last: game.last, plies: game.plies })
  if (game.history.length > 12) game.history.shift()
}

/** Plays a legal move for the side to move and decides whether the game is over. */
export function play(game: Game, move: Move, mandatory: boolean) {
  const piece = game.board[move.from]
  apply(game.board, move)
  const man = piece === 1 || piece === -1
  game.quiet = move.caps.length || man ? 0 : game.quiet + 1
  game.last = game.last.length && game.last[game.last.length - 1] ? [game.last[game.last.length - 1], move] : [move]
  game.turn = -game.turn
  game.plies++
  if (!legalMoves(game.board, game.turn, mandatory).length) game.winner = -game.turn
  else if (game.quiet >= DRAW_PLIES) game.winner = DRAW
}

/** Back to the position kept last. */
export function undo(game: Game): boolean {
  const back = game.history.pop()
  if (!back) return false
  game.board = back.board
  game.turn = back.turn
  game.quiet = back.quiet
  game.last = back.last
  game.winner = 0
  game.plies = Number(back.plies) || 0
  return true
}

/** A game read back from state, or null when it is not one. */
export function readGame(value: any): Game | null {
  if (!value || typeof value !== 'object' || !Array.isArray(value.board) || value.board.length !== 64) return null
  return {
    board: value.board.map((v: any) => Number(v) || 0),
    turn: value.turn === -1 ? -1 : 1,
    quiet: Number(value.quiet) || 0,
    last: Array.isArray(value.last) ? value.last.filter((m: any) => m && Array.isArray(m.path)) : [],
    winner: Number(value.winner) || 0,
    history: Array.isArray(value.history) ? value.history : [],
    seed: Number(value.seed) | 0,
    plies: Number(value.plies) || 0,
  }
}
